using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
public static class RuinsColumnPartsReview{
 [Serializable]public class Probe{public string kind;public float x,y,z;}[Serializable]public class Probes{public Probe[] probes;}
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static Color32[] Shot(Camera c,Vector3 from,Vector3 at,string f){c.transform.position=from;c.transform.LookAt(at);var rt=new RenderTexture(1200,900,24);c.targetTexture=rt;for(int i=0;i<3;i++)c.Render();var old=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(1200,900,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1200,900),0,0);t.Apply();File.WriteAllBytes(f,t.EncodeToPNG());var pixels=t.GetPixels32();RenderTexture.active=old;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(t);return pixels;}
 public static void Run(){const string ev="Evidence/Target32Columns";Directory.CreateDirectory(ev);try{
 EditorSceneManager.OpenScene("Assets/RuinsTarget32Output/Room.unity");var root=GameObject.Find("ruins_1").transform.parent.gameObject;var c=UnityEngine.Object.FindAnyObjectByType<Camera>();var sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).Single(x=>x.type==LightType.Directional);sun.transform.rotation=Quaternion.Euler(38,-28,0);RenderSettings.ambientLight=Color.gray*.65f;c.orthographic=false;c.backgroundColor=new Color(.075f,.085f,.1f);
 var before=Shot(c,new Vector3(15,20,19),new Vector3(0,3.5f,0),ev+"/room.png");UnityEngine.Object.DestroyImmediate(root);root=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget32Output/Structures/Ruins.prefab"));Check(before.SequenceEqual(Shot(c,c.transform.position,new Vector3(0,3.5f,0),ev+"/prefab.png")),"Prefab image");
 var saved="Assets/RuinsTarget32Output/ColumnPersistence.unity";EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),saved);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);EditorSceneManager.OpenScene(saved);root=GameObject.Find("ruins_1").transform.parent.gameObject;c=UnityEngine.Object.FindAnyObjectByType<Camera>();sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).Single(x=>x.type==LightType.Directional);Check(before.SequenceEqual(Shot(c,new Vector3(15,20,19),new Vector3(0,3.5f,0),ev+"/scene.png")),"Scene image");
 Physics.SyncTransforms();int supports=0;foreach(var id in new[]{31,32,34,35}){var top=root.transform.Find("ruins_"+id);var bottom=root.transform.Find("ruins_"+(id-1));var collider=bottom.GetComponent<MeshCollider>();foreach(float x in new[]{-.18f,0,.18f})foreach(float z in new[]{-.18f,0,.18f}){var point=top.position+new Vector3(x,.02f,z);Check(collider.Raycast(new Ray(point,Vector3.down),out var hit,.05f),"Support miss "+id);Check(Math.Abs(hit.point.y-top.position.y)<.0001f,"Support gap "+id);supports++;}}
 var probes=JsonUtility.FromJson<Probes>(File.ReadAllText("Assets/Editor/column-parts-probes.json"));float delta=0;foreach(var p in probes.probes){int id=p.kind=="column_base"?30:p.kind=="column_shaft"?31:32;var t=root.transform.Find("ruins_"+id);var collider=t.GetComponent<MeshCollider>();Check(collider.Raycast(new Ray(t.position+new Vector3(p.x,8,p.z),Vector3.down),out var hit,10),"Surface miss");delta=Math.Max(delta,Math.Abs(hit.point.y-t.position.y-p.y));}Check(delta<.001f&&probes.probes.Length>300,"Web native surfaces");
 foreach(int id in new[]{30,31,32}){var template=root.transform.Find("ruins_"+id).gameObject;Check(template.GetComponent<MeshFilter>().sharedMesh==template.GetComponent<MeshCollider>().sharedMesh,"Collider identity");foreach(int n in new[]{9,225}){var clones=Enumerable.Range(0,n).Select(i=>{var o=UnityEngine.Object.Instantiate(template);o.transform.position=new Vector3(100+i*2,3,100);return o;}).ToArray();Check(clones.Select(o=>o.GetComponent<MeshFilter>().sharedMesh).Distinct().Count()==1&&clones.Select(o=>o.GetComponent<MeshRenderer>().sharedMaterial).Distinct().Count()==1,"Sharing");foreach(var o in clones)UnityEngine.Object.DestroyImmediate(o);}}
 var baseline=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget30Output/Structures/Ruins.prefab"));for(int i=30;i<=37;i++)root.transform.Find("ruins_"+i).gameObject.SetActive(false);root.SetActive(false);var oldPixels=Shot(c,new Vector3(15,20,19),new Vector3(0,3.5f,0),ev+"/unchanged-before.png");baseline.SetActive(false);root.SetActive(true);Check(oldPixels.SequenceEqual(Shot(c,new Vector3(15,20,19),new Vector3(0,3.5f,0),ev+"/unchanged-after.png")),"Old kit changed");UnityEngine.Object.DestroyImmediate(baseline);foreach(Transform child in root.transform)child.gameObject.SetActive(int.TryParse(child.name.Replace("ruins_",""),out var id)&&id>=30);
 Shot(c,new Vector3(12,8,13),new Vector3(6.8f,4.3f,7.5f),ev+"/assembled-close.png");sun.transform.rotation=Quaternion.Euler(27,130,0);Shot(c,new Vector3(12,8,13),new Vector3(6.8f,4.3f,7.5f),ev+"/assembled-opposite.png");sun.transform.rotation=Quaternion.Euler(38,-28,0);
 foreach(var pair in new[]{(30,"base"),(31,"shaft"),(32,"capital")}){foreach(Transform child in root.transform)child.gameObject.SetActive(child.name=="ruins_"+pair.Item1);var t=root.transform.Find("ruins_"+pair.Item1);var center=t.GetComponent<MeshRenderer>().bounds.center;c.orthographic=true;c.orthographicSize=pair.Item1==31?1.5f:.8f;Shot(c,center+new Vector3(3,2.2f,4),center,ev+"/"+pair.Item2+"-close.png");}
 Check(!ShaderUtil.ShaderHasError(Shader.Find("MapRuins/AgedLimestone")),"Shader errors");File.WriteAllText(ev+"/result.json","{\"pass\":true,\"supportSamples\":"+supports+",\"surfaceSamples\":"+probes.probes.Length+",\"maxSurfaceDelta\":"+delta.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"prefabScenePixelDelta\":0,\"previousKitPixelDelta\":0,\"shared9And225\":true,\"GPUmeasured\":false}");EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(ev+"/failure.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}
